document.addEventListener('DOMContentLoaded', () => {
  const taskForm = document.getElementById('taskForm');
  const taskContainer = document.getElementById('taskContainer');
  const filterButtons = document.querySelectorAll('.filter-btn');

  let currentFilter = 'all';

  // Form submission
  taskForm.addEventListener('submit', async (e) => {
    e.preventDefault();

    const title = document.getElementById('title').value.trim();
    const description = document.getElementById('description').value.trim();

    if (!title) return;

    try {
      const response = await fetch('/api/tasks', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ title, description })
      });

      if (response.ok) {
        taskForm.reset();
        fetchTasks();
      } else {
        console.error('Failed to create task');
      }
    } catch (error) {
      console.error('Error:', error);
    }
  });

  // Filter buttons
  filterButtons.forEach(button => {
    button.addEventListener('click', () => {
      filterButtons.forEach(btn => btn.classList.remove('active'));
      button.classList.add('active');
      currentFilter = button.dataset.filter;
      fetchTasks();
    });
  });

  // Fetch tasks
  async function fetchTasks() {
    try {
      const response = await fetch(`/api/tasks?filter=${currentFilter}`);
      const tasks = await response.json();
      renderTasks(tasks);
    } catch (error) {
      console.error('Error fetching tasks:', error);
    }
  }

  // Render tasks
  function renderTasks(tasks) {
    taskContainer.innerHTML = '';

    if (tasks.length === 0) {
      taskContainer.innerHTML = '<p>No tasks found</p>';
      return;
    }

    tasks.forEach(task => {
      const taskElement = document.createElement('div');
      taskElement.className = `task-item ${task.completed ? 'completed' : ''}`;
      taskElement.innerHTML = `
        <div class="task-content">
          <h3>${escapeHtml(task.title)}</h3>
          <p>${escapeHtml(task.description || '')}</p>
        </div>
        <div class="task-actions">
          <button class="edit-btn" data-id="${task.id}">Edit</button>
          <button class="complete-btn" data-id="${task.id}">${task.completed ? 'Undo' : 'Complete'}</button>
          <button class="delete-btn" data-id="${task.id}">Delete</button>
        </div>
      `;

      taskContainer.appendChild(taskElement);
    });

    // Add event listeners to buttons
    document.querySelectorAll('.edit-btn').forEach(button => {
      button.addEventListener('click', handleEdit);
    });

    document.querySelectorAll('.complete-btn').forEach(button => {
      button.addEventListener('click', handleComplete);
    });

    document.querySelectorAll('.delete-btn').forEach(button => {
      button.addEventListener('click', handleDelete);
    });
  }

  // Handle edit
  async function handleEdit(e) {
    const id = e.target.dataset.id;
    const task = await fetchTaskById(id);

    if (!task) return;

    const newTitle = prompt('Edit title:', task.title);
    if (newTitle === null) return;

    const newDescription = prompt('Edit description:', task.description || '');
    if (newDescription === null) return;

    try {
      const response = await fetch(`/api/tasks/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          title: newTitle.trim(),
          description: newDescription.trim(),
          completed: task.completed
        })
      });

      if (response.ok) {
        fetchTasks();
      } else {
        console.error('Failed to update task');
      }
    } catch (error) {
      console.error('Error:', error);
    }
  }

  // Handle complete
  async function handleComplete(e) {
    const id = e.target.dataset.id;
    const task = await fetchTaskById(id);

    if (!task) return;

    try {
      const response = await fetch(`/api/tasks/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          title: task.title,
          description: task.description,
          completed: !task.completed
        })
      });

      if (response.ok) {
        fetchTasks();
      } else {
        console.error('Failed to update task');
      }
    } catch (error) {
      console.error('Error:', error);
    }
  }

  // Handle delete
  async function handleDelete(e) {
    const id = e.target.dataset.id;

    if (!confirm('Are you sure you want to delete this task?')) return;

    try {
      const response = await fetch(`/api/tasks/${id}`, {
        method: 'DELETE'
      });

      if (response.ok) {
        fetchTasks();
      } else {
        console.error('Failed to delete task');
      }
    } catch (error) {
      console.error('Error:', error);
    }
  }

  // Fetch single task by ID
  async function fetchTaskById(id) {
    try {
      const response = await fetch(`/api/tasks/${id}`);
      if (response.ok) {
        return await response.json();
      }
      return null;
    } catch (error) {
      console.error('Error fetching task:', error);
      return null;
    }
  }

  // Escape HTML to prevent XSS
  function escapeHtml(text) {
    const map = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#039;'
    };
    return text.replace(/[&<>"]/g, m => map[m]);
  }

  // Initial fetch
  fetchTasks();
});

import { open } from 'node:sqlite';
import { sqlite3 } from 'node:sqlite';

// Open the database file
const db = await open({
  filename: './tasks.db',
  driver: sqlite3.Database
});

// Initialize the database
await db.exec(`
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    completed BOOLEAN NOT NULL DEFAULT 0
  )
`);

// Database operations
export async function createTask(title, description) {
  return db.run(
    'INSERT INTO tasks (title, description) VALUES (?, ?)',
    [title, description]
  );
}

export async function getTasks(filter = 'all') {
  let query = 'SELECT * FROM tasks';
  if (filter === 'active') {
    query += ' WHERE completed = 0';
  } else if (filter === 'completed') {
    query += ' WHERE completed = 1';
  }
  query += ' ORDER BY id DESC';
  return db.all(query);
}

export async function getTaskById(id) {
  return db.get('SELECT * FROM tasks WHERE id = ?', [id]);
}

export async function updateTask(id, title, description, completed) {
  return db.run(
    'UPDATE tasks SET title = ?, description = ?, completed = ? WHERE id = ?',
    [title, description, completed ? 1 : 0, id]
  );
}

export async function deleteTask(id) {
  return db.run('DELETE FROM tasks WHERE id = ?', [id]);
}

// Close the database connection when the app exits
process.on('exit', () => {
  db.close();
});

import { createServer } from 'node:http';
import { open } from 'node:sqlite';
import { sqlite3 } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import 
  { createTask, 
    getTasks, 
    getTaskById, 
    updateTask, 
    deleteTask 
  } from './database.js';

const server = createServer(async (req, res) => {
  // Set CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  // Handle preflight requests
  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    return res.end();
  }

  // Parse URL
  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;

  // API Routes
  if (path.startsWith('/api/')) {
    try {
      if (path === '/api/tasks' && req.method === 'GET') {
        const filter = url.searchParams.get('filter') || 'all';
        const tasks = await getTasks(filter);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify(tasks));
      }

      if (path === '/api/tasks' && req.method === 'POST') {
        let body = '';
        for await (const chunk of req) {
          body += chunk.toString();
        }
        const { title, description } = JSON.parse(body);
        const result = await createTask(title, description);
        res.writeHead(201, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ id: result.lastID, title, description, completed: false }));
      }

      if (path.startsWith('/api/tasks/') && req.method === 'GET') {
        const id = path.split('/').pop();
        const task = await getTaskById(id);
        if (task) {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          return res.end(JSON.stringify(task));
        } else {
          res.writeHead(404);
          return res.end('Task not found');
        }
      }

      if (path.startsWith('/api/tasks/') && req.method === 'PUT') {
        const id = path.split('/').pop();
        let body = '';
        for await (const chunk of req) {
          body += chunk.toString();
        }
        const { title, description, completed } = JSON.parse(body);
        await updateTask(id, title, description, completed);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ id, title, description, completed }));
      }

      if (path.startsWith('/api/tasks/') && req.method === 'DELETE') {
        const id = path.split('/').pop();
        await deleteTask(id);
        res.writeHead(200);
        return res.end();
      }

      res.writeHead(404);
      return res.end('Not found');
    } catch (error) {
      console.error('API Error:', error);
      res.writeHead(500);
      return res.end('Internal Server Error');
    }
  }

  // Static file serving
  try {
    let filePath = path === '/' ? 'index.html' : path.substring(1);

    // Security check to prevent directory traversal
    if (filePath.includes('..') || filePath.startsWith('/')) {
      res.writeHead(403);
      return res.end('Forbidden');
    }

    const fileContent = await readFile(join(new URL('.', import.meta.url).pathname, filePath));

    // Set appropriate content type
    if (filePath.endsWith('.html')) {
      res.setHeader('Content-Type', 'text/html');
    } else if (filePath.endsWith('.js')) {
      res.setHeader('Content-Type', 'application/javascript');
    } else if (filePath.endsWith('.css')) {
      res.setHeader('Content-Type', 'text/css');
    }

    res.writeHead(200);
    return res.end(fileContent);
  } catch (error) {
    if (error.code === 'ENOENT') {
      res.writeHead(404);
      return res.end('Not found');
    }
    console.error('Static file error:', error);
    res.writeHead(500);
    return res.end('Internal Server Error');
  }
});

const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

